  let aS=0,iS=0,cross=0,waves=[];
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wA=Math.sin(d*f-t*sp),wI=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    waves.push(wA);aS+=wA;iS+=wI;
  }
  for(let j=0;j<8;j++)for(let k=j+1;k<8;k++)cross+=waves[j]*waves[k]*0.12;
  const n=8,act=aS/n,inh=iS/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.08*Math.cos(t*0.1)+sy*0.06*Math.sin(t*0.15)+t*1.5)*0.15;
