  let minD=999,secD=999;
  for(const[sX,sY]of src){const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);if(d<minD){secD=minD;minD=d;}else if(d<secD)secD=d;}
  const voronoi=Math.sin((secD-minD)*0.15+t*1.2)*0.3;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+cross*0.5+voronoi)*2.0);
  const detail=Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin(sx*0.3+t*2)*Math.sin(sy*0.25-t*1.5)*0.5;
