  const blend=reaction*0.6+cell*0.2+voronoi*0.2,v=blend*0.5+0.5;
  const pal=[[6,12,52],[12,42,85],[18,78,105],[22,130,120],[45,160,100],[160,175,50],[210,185,55],[215,145,60],[195,95,65],[170,60,70],[130,35,85],[70,22,72],[30,15,60],[6,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15,edge=Math.abs(reaction)>0.7?1.12:1.0,glow=Math.max(0,Math.sin(cross*2))*0.15;
  return[Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*80)|0),Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*40)|0),Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*20)|0)];
